    question: '表は、コンクリートの計画調合において使用する材料の絶対容積及び質量を記号で表したものである(水の絶対容積P、セメントの絶対容積Q、細骨材の絶対容積R、粗骨材の絶対容積S／水の質量W、セメントの質量X、細骨材の質量Y、粗骨材の質量Z)。この表の材料を使用したコンクリートに関する次の記述のうち、最も不適当なものはどれか。ただし、細骨材及び粗骨材は、表面乾燥飽水状態とする。',
